          select sbid from (
             select id as sbid
             from tl_bjts.sb_sbxx_hz t, gs_dj_cktmsdab d
             where t.nsrdzdah = d.nsrdzdah
                 and d.cpcode = #{djxh}
                 and t.sbywb_dm = #{sbywbDm,jdbcType=VARCHAR}
